// T19 C9: auto title (part 2 §26). While a project is still "Untitled Project" (title_source 'default'), its title is
// generated by the user's model from Xapp's request `{message, assets[{name: analysis summary or file name, type}]}`.
// Failure or no provider → the title stays; a renamed project is never retitled (setGeneratedTitle checks again).
// Default: wait for the first analysis summaries, then ask once. Parity mode: ask once per editor open (Xapp, W3-SH-01).
// Review finding 4 (notes Q12): when every linked asset has settled with no summary (audio only, vision unavailable),
// the default asks once with the file names, Xapp's own fallback; an empty project waits for an attach, not a timer.
import { DEFAULT_TITLE } from '../store/database';
import type { ProjectStore } from '../store/database';
import type { Asset, ProjectRecord } from '../store/model';
import type { AnalysisRow } from './service';

/** The chat-provider shape (T20 providers; `parity/provider.ts` MockProvider in tests): text events are the answer. */
export type TitleProvider = { stream(request: { messages: unknown[]; purpose?: string }, signal?: AbortSignal): AsyncIterable<{ type: string; text?: string }> };
export type TitleRequest = { message: string; assets: { name: string; type: Asset['type'] }[] };
export type TitleOutcome = 'titled' | 'kept' | 'waiting' | 'empty' | 'no-provider' | 'failed';
type Store = Pick<ProjectStore, 'library' | 'row' | 'setGeneratedTitle' | 'attached'>;

/** Cutframe guard (Xapp's limit is not recorded). */
export const TITLE_MAX = 100, TITLE_POLL_MS = 5000;
/** The connected model provider (settings/providers.ts); with none the title stays "Untitled Project". */
let current: TitleProvider | undefined;
/** Watches waiting for a provider: woken when one is set (no idle timer while none is connected). */
const waiting = new Set<() => void>();
export const setTitleProvider = (provider: TitleProvider | undefined) => { current = provider; if (provider) for (const wake of [...waiting]) wake(); };

const PROMPT = 'Write a short title (at most 8 words) for a video project made from these assets. Reply with the title only.';
/** The first non-empty line, without a "Title:" label, surrounding quotes or extra spaces. */
export const cleanTitle = (text: string) => (text.split('\n').map(s => s.trim()).find(Boolean) ?? '').replace(/^title:\s*/i, '')
  .replace(/^["'“‘]+|["'”’]+$/g, '').replace(/\s+/g, ' ').trim().slice(0, TITLE_MAX).trim();

/** = /api/generate/project-title: the title, or null when the model fails or answers nothing. */
export async function generateTitle(provider: TitleProvider, request: TitleRequest, signal?: AbortSignal): Promise<string | null> {
  try {
    let text = '';
    for await (const event of provider.stream({ messages: [{ role: 'user', content: `${PROMPT}\n${JSON.stringify(request)}` }], purpose: 'project-title' }, signal)) {
      if (event.type === 'text' && event.text) text += event.text;
    }
    return cleanTitle(text) || null;
  } catch { return null; }
}

/** The project's assets in link order, each with its analysis summary or else its file name. `pending`: some linked asset
 *  is still uploading or being prepared (its summary may still come). */
export async function titleRequest(store: Pick<Store, 'library' | 'row'>, projectId: string): Promise<{ request: TitleRequest; summaries: number; pending: boolean }> {
  const { assets, links } = await store.library(), byId = new Map(assets.map(a => [a.id, a]));
  const linked = links.filter(l => l.projectId === projectId && l.deleted_at === null).sort((a, b) => a.added_at.localeCompare(b.added_at)).flatMap(l => byId.get(l.assetId) ?? []);
  let summaries = 0;
  const list = await Promise.all(linked.map(async a => {
    const summary = (await store.row<AnalysisRow>('analyses', a.id))?.analysis.summary?.trim();
    if (summary) summaries++;
    return { name: summary || a.name, type: a.type };
  }));
  const pending = linked.some(a => a.processing_status === 'uploading' || a.processing_status === 'processing');
  return { request: { message: '', assets: list }, summaries, pending };
}

/** One attempt. `waiting` = not yet (default mode: no summary while an asset is still being prepared); the caller may try
 *  again later. `empty` = default mode, no linked asset yet. */
export async function autoTitle(store: Store, projectId: string, options: { provider?: TitleProvider; parity?: boolean; signal?: AbortSignal } = {}): Promise<TitleOutcome> {
  if (!options.provider) return 'no-provider';
  const record = await store.row<ProjectRecord>('projects', projectId);
  if (!record || record.title !== DEFAULT_TITLE || (record.title_source ?? 'default') !== 'default') return 'kept';
  if (record.processing_status !== 'ready') return 'waiting';
  const { request, summaries, pending } = await titleRequest(store, projectId);
  if (!options.parity && !summaries && !request.assets.length) return 'empty';
  if (!options.parity && !summaries && pending) return 'waiting';
  const title = await generateTitle(options.provider, request, options.signal);
  if (options.signal?.aborted) return 'kept';
  if (!title) return 'failed';
  return await store.setGeneratedTitle(projectId, title) ? 'titled' : 'kept';
}

/** The editor-open hook: parity asks once; the default re-checks every TITLE_POLL_MS while an asset is still being
 *  prepared, waits for the project's first attach while it has none and for setTitleProvider while no provider is
 *  connected (no timer for either), and stops after a title, a rename or one failure. Returns stop.
 *  The attach watch is subscribed before each default check, so an attach that commits while the check reads is not
 *  missed (re-review nit a). It sees attaches made in this tab only; another tab's attach is seen when the editor reopens. */
export function watchTitle(store: Store, projectId: string, options: { parity?: boolean; provider?: () => TitleProvider | undefined; onTitle?: (title: string) => void; timers?: Pick<typeof globalThis, 'setTimeout' | 'clearTimeout'> } = {}): () => void {
  const controller = new AbortController(), timers = options.timers ?? globalThis, provider = options.provider ?? (() => current);
  let timer: ReturnType<typeof setTimeout> | undefined, idle = false, seen = false;
  const wake = () => { waiting.delete(wake); void check(); };
  // `seen`: this project got an attach since the running check began; `idle`: the last check found it empty and none runs.
  const attached = (id: string) => { if (id !== projectId) return; seen = true; if (idle) { idle = false; void check(); } };
  const check = async () => {
    if (!options.parity) { seen = false; store.attached.add(attached); }
    const outcome = await autoTitle(store, projectId, { provider: provider(), parity: options.parity, signal: controller.signal }).catch(() => 'failed' as const);
    if (controller.signal.aborted) return;
    if (outcome !== 'empty') store.attached.delete(attached);
    if (outcome === 'titled') { const title = (await store.row<ProjectRecord>('projects', projectId))?.title; if (title && !controller.signal.aborted) options.onTitle?.(title); }
    else if (!options.parity && outcome === 'waiting') timer = timers.setTimeout(() => void check(), TITLE_POLL_MS);
    else if (!options.parity && outcome === 'empty') { if (seen) void check(); else idle = true; }
    else if (!options.parity && outcome === 'no-provider') waiting.add(wake);
  };
  void check();
  return () => { controller.abort(); waiting.delete(wake); store.attached.delete(attached); if (timer !== undefined) timers.clearTimeout(timer); };
}
